/**
 * The id of a row a plan creates in bulk (Generators bulk programme, plan §2.5: ids are pre-generated by the caller).
 *
 * THE SINGLE SANCTIONED IMPURE DEFAULT of the plan builders in `features/pm/generators/rules.ts`: a builder takes
 * `opts.newId` and falls back to this, so a plan stays a pure function of its arguments in every test (a test injects a
 * counter) and `rules.ts` itself never calls `crypto`. Do not add other callers inside a `rules.ts`.
 */
export function newRowId(): string {
  return crypto.randomUUID();
}
